  alvo.innerHTML = "\n\n<header>\n  <div class=\"bar\">\n    <a href=\"/auto-curadoria\"><img src=\"https://psasite.vercel.app/_next/image?url=%2Fbrand%2Flogos%2Flogo-01.png&w=256&q=75\" alt=\"PSA Palestras\"></a>\n    <span class=\"eyebrow\">Auto Curadoria</span>\n    <a class=\"volta\" href=\"/auto-curadoria\">← voltar</a>\n  </div>\n</header>\n\n<main class=\"wrap\">\n\n  <!-- 0. acesso (paywall por CPF/CNPJ) -->\n  <section class=\"passo on\" id=\"gate\">\n    <span class=\"eyebrow\">Acesso</span>\n    <h1>Vamos começar<br>sua curadoria.</h1>\n    <p class=\"sub\">Digite o CPF ou CNPJ usado na compra da Auto Curadoria para liberar o seu briefing.</p>\n    <div class=\"campos\">\n      <div><label for=\"documento\">CPF ou CNPJ <span>*</span></label><input id=\"documento\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Somente números\"></div>\n    </div>\n    <p class=\"erro\" id=\"eGate\"></p>\n    <div class=\"acoes\">\n      <button class=\"btn btn--primary\" id=\"btnAcesso\">Iniciar curadoria →</button>\n      <!-- aparece só quando NÃO há compra liberada: leva ao checkout -->\n      <a class=\"btn\" id=\"btnComprar\" href=\"https://checkout.profissionaissa.com.br/curadoria/checkout/4fbc7e0d-c39c-4241-9334-ef62c2326b55\" style=\"display:none;background:#16a34a;color:#fff;box-shadow:0 0 40px #16a34a55\">Adquirir Curadoria →</a>\n    </div>\n    <!-- aparece quando já existe curadoria com este CPF e ainda há refação: escolher -->\n    <div id=\"escolha\" style=\"display:none\">\n      <p class=\"sub\" style=\"margin-top:var(--s-6)\">Você já tem uma curadoria com este CPF/CNPJ. O que você prefere?</p>\n      <div class=\"acoes\">\n        <button class=\"btn btn--primary\" id=\"btnRetomar\">Retomar minha curadoria →</button>\n        <a class=\"btn\" id=\"btnCriarNova\" href=\"https://checkout.profissionaissa.com.br/curadoria/checkout/4fbc7e0d-c39c-4241-9334-ef62c2326b55\" style=\"background:#16a34a;color:#fff;box-shadow:0 0 40px #16a34a55\">Criar nova curadoria →</a>\n      </div>\n    </div>\n  </section>\n\n  <!-- conversa com o Santiago (curador) -->\n  <section class=\"passo\" id=\"chat\">\n    <div class=\"santi-header\">\n      <div class=\"santi-av\" id=\"santiAv\">\n        <video class=\"santi-vid\" data-estado=\"idle\" autoplay loop muted playsinline preload=\"auto\" poster=\"https://psa-auto-curadoria.vercel.app/santiago.png\"><source src=\"https://psa-auto-curadoria.vercel.app/santiago.mp4\" type=\"video/mp4\"></video>\n        <video class=\"santi-vid\" data-estado=\"pensando\" loop muted playsinline preload=\"auto\" hidden><source src=\"https://psa-auto-curadoria.vercel.app/santiago-pensando.mp4\" type=\"video/mp4\"></video>\n        <video class=\"santi-vid\" data-estado=\"falando\" loop muted playsinline preload=\"auto\" hidden><source src=\"https://psa-auto-curadoria.vercel.app/santiago-falando.mp4\" type=\"video/mp4\"></video>\n      </div>\n      <div class=\"santi-nome\">Santiago<small>curador responsável pela sua demanda</small></div>\n      <span class=\"santi-dot\"></span>\n    </div>\n    <div class=\"chat-topo\" style=\"justify-content:flex-end;margin-bottom:var(--s-5)\">\n      <a class=\"dica\" id=\"chat-para-form\" style=\"cursor:pointer;text-decoration:underline\">prefiro preencher um formulário</a>\n    </div>\n    <div id=\"chatMsgs\" class=\"chat-msgs\"></div>\n    <div id=\"chatEntrada\" class=\"chat-entrada\"></div>\n  </section>\n\n  <div class=\"prog\" id=\"prog\" style=\"display:none\"><i class=\"on\"></i><i></i><i></i></div>\n\n  <!-- 1. contato -->\n  <section class=\"passo\" id=\"p1\">\n    <span class=\"eyebrow\">Passo 1 de 3</span>\n    <h1>Quem está<br>organizando?</h1>\n    <p class=\"sub\">Precisamos saber com quem falar quando a curadoria ficar pronta.</p>\n    <div class=\"campos\">\n      <div class=\"dupla\">\n        <div><label for=\"nome\">Nome do responsável <span>*</span></label><input id=\"nome\" autocomplete=\"name\" placeholder=\"Como podemos te chamar\"></div>\n        <div><label for=\"empresa\">Empresa <span>*</span></label><input id=\"empresa\" autocomplete=\"organization\" placeholder=\"Razão social ou nome fantasia\"></div>\n      </div>\n      <div class=\"dupla\">\n        <div><label for=\"email\">E-mail corporativo <span>*</span></label><input id=\"email\" type=\"email\" autocomplete=\"email\" placeholder=\"voce@empresa.com.br\"></div>\n        <div><label for=\"telefone\">Telefone <span>*</span></label><input id=\"telefone\" inputmode=\"tel\" autocomplete=\"tel\" placeholder=\"(11) 99999-9999\"></div>\n      </div>\n    </div>\n    <p class=\"erro\" id=\"e1\"></p>\n    <div class=\"acoes\"><button class=\"btn btn--primary\" data-vai=\"2\">Continuar →</button></div>\n  </section>\n\n  <!-- 2. evento -->\n  <section class=\"passo\" id=\"p2\">\n    <span class=\"eyebrow\">Passo 2 de 3</span>\n    <h1>Sobre<br>o evento.</h1>\n    <p class=\"sub\">Esses são os filtros que a curadoria usa para eliminar quem não serve.</p>\n    <div class=\"campos\">\n      <div class=\"dupla\">\n        <div><label for=\"macroTema\">Tema do evento <span>*</span></label><select id=\"macroTema\"><option value=\"\">Selecione</option></select></div>\n        <div><label for=\"microTema\">Recorte do tema</label><select id=\"microTema\"><option value=\"\">Selecione o tema primeiro</option></select></div>\n      </div>\n      <div class=\"dupla\">\n        <div><label for=\"publicoAlvo\">Público-alvo do evento <span>*</span></label><select id=\"publicoAlvo\"><option value=\"\">Selecione</option></select></div>\n        <div><label for=\"formato\">Formato <span>*</span></label><select id=\"formato\"><option value=\"\">Selecione</option></select></div>\n      </div>\n      <div class=\"dupla\">\n        <div><label for=\"data\">Qual a data? <span>*</span></label><input id=\"data\" type=\"date\"></div>\n        <div><label for=\"horario\">Horário <span>*</span></label><input id=\"horario\" type=\"time\"></div>\n      </div>\n      <div class=\"dupla\">\n        <div><label for=\"duracao\">Duração do evento <span>*</span></label><select id=\"duracao\"><option value=\"\">Selecione</option></select></div>\n        <div><label for=\"localEvento\">Local do evento <span>*</span></label><input id=\"localEvento\" placeholder=\"Ex: Auditório da sede, Hotel Bourbon\"></div>\n      </div>\n      <div class=\"dupla\">\n        <div><label for=\"local\">Estado <span>*</span></label><select id=\"local\"><option value=\"\">Selecione</option></select></div>\n        <div><label for=\"cidade\">Cidade <span>*</span></label><select id=\"cidade\" disabled><option value=\"\">Selecione o estado primeiro</option></select></div>\n      </div>\n      <div class=\"dupla\">\n        <div><label for=\"orcamento\">Orçamento <span>*</span></label><select id=\"orcamento\"><option value=\"\">Selecione</option></select></div>\n        <div><label for=\"vendaIngresso\">Evento com venda de ingresso? <span>*</span></label><select id=\"vendaIngresso\"><option value=\"\">Selecione</option></select></div>\n      </div>\n    </div>\n    <p class=\"erro\" id=\"e2\"></p>\n    <div class=\"acoes\">\n      <button class=\"btn btn--primary\" data-vai=\"3\">Continuar →</button>\n      <button class=\"btn btn--ghost\" data-vai=\"1\">Voltar</button>\n    </div>\n  </section>\n\n  <!-- 3. briefing -->\n  <section class=\"passo\" id=\"p3\">\n    <span class=\"eyebrow\">Passo 3 de 3</span>\n    <h1>O que precisa<br>acontecer.</h1>\n    <p class=\"sub\">Aqui é onde a curadoria fica boa. Estas duas respostas são o que mais muda a indicação.</p>\n    <div class=\"campos\">\n      <div>\n        <label for=\"motivacao\">O que motivou você a procurar essa temática? <span>*</span></label>\n        <select id=\"motivacao\"><option value=\"\">Selecione</option></select>\n      </div>\n      <div>\n        <label for=\"sentimento\">Como você gostaria que os espectadores se sentissem após o término do evento? <span>*</span></label>\n        <select id=\"sentimento\"><option value=\"\">Selecione</option></select>\n      </div>\n      <div>\n        <label for=\"briefing\">Quer acrescentar algum contexto?</label>\n        <textarea id=\"briefing\" placeholder=\"Momento da empresa, assunto que não pode ser tocado, palestrante que já contrataram e o que funcionou (ou não).\"></textarea>\n        <p class=\"dica\">Opcional, mas se já teve um evento que deu certo ou errado, conte — é o que mais afina a escolha.</p>\n      </div>\n    </div>\n    <p class=\"erro\" id=\"e3\"></p>\n    <div class=\"acoes\">\n      <button class=\"btn btn--primary\" id=\"enviar\">Gerar minha curadoria →</button>\n      <button class=\"btn btn--ghost\" data-vai=\"2\">Voltar</button>\n    </div>\n  </section>\n\n  <!-- carregando -->\n  <section class=\"passo\" id=\"carregando\">\n    <div class=\"anel\"></div>\n    <p id=\"pensando\">Lendo seu briefing…</p>\n    <div class=\"barra\"><i id=\"barraFill\"></i></div>\n    <p id=\"restante\" class=\"dica\" style=\"text-align:center\"></p>\n    <div class=\"passos-ia\" id=\"passosIa\"></div>\n    <!-- só aparece depois que o briefing volta com id: antes disso não há link para salvar -->\n    <div class=\"acoes\" id=\"salvarLink\" hidden style=\"justify-content:center\">\n      <button class=\"btn btn--ghost\" data-copiar>Salvar link desta curadoria</button>\n    </div>\n    <p class=\"dica\" id=\"salvarDica\" hidden style=\"text-align:center\">Guarde o link e volte quando quiser — a curadoria fica salva nele.</p>\n  </section>\n\n  <!-- resultado -->\n  <section class=\"passo\" id=\"resultado\"></section>\n\n</main>\n\n";

